import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_range(start, end):
    """Calculates LCM(start, start+1, ..., end)"""
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

def check_n(n, max_k):
    results = {}
    for k in range(1, max_k + 1):
        # x_k = lcm(k, k+1, ..., k+n-1)
        x_k = lcm_of_range(k, k + n - 1)

        # x_{k+1} = lcm(k+1, k+2, ..., k+n)
        x_k_plus_1 = lcm_of_range(k + 1, k + n)

        comparison = ""
        if x_k_plus_1 > x_k:
            comparison = "Increase (>)"
        elif x_k_plus_1 == x_k:
            comparison = "Same (=)"
        else: # x_{k+1} < x_k
            comparison = "Decrease (<)"

        results[k] = (x_k, x_k_plus_1, comparison)
    return results

# Test n=3
n3_results = check_n(3, 15)
print(f"--- Results for n=3 (k=1 to 15) ---")
for k, (xk, xk1, comp) in n3_results.items():
    print(f"k={k}: x_k={xk}, x_{k+1}={xk1}, Trend: {comp}")

# Test n=4
n4_results = check_n(4, 15)
print(f"\n--- Results for n=4 (k=1 to 15) ---")
